(* [comment removed for export] *)
Local Ltac slia_consumed_abort :=
  match goal with
  | |- context [(?A + ?s <= ?A \/ ?h <= ?A)%Z] =>
      first [ assert (A < A + s /\ A < h)%Z by (zify_prune; xlia_noeuclid); fail 2 | fail ]
  | |- _ => idtac
  end.
Local Ltac slia ::= first [ exact I | slia_consumed_abort; slia2w ].
(* [comment removed for export] *)
Tactic Notation "callZc" uconstr(SPEC) tactic3(CLR) :=
  lazymatch goal with
  | |- evt ?segs _ (MS _ _ _ _ _ ?m _) => eapply evt_cut; [ eapply SPEC | CLR; post_callZ segs m ]
  end.
Local Ltac clr_stk := idtac; match goal with STx : stk _ _ _ _ |- _ => clear STx end.
(* [comment removed for export] *)
Local Ltac simpl_arr_sizes ::= idtac.
(* [comment removed for export] *)
(* [comment removed for export] *)
Local Ltac fast_eassumption :=
  first [ lazymatch goal with
          | |- rw_cells _ _ ?A _ => match goal with H : rw_cells _ _ A _ |- _ => exact H end
          | |- ro_cells _ _ ?A _ => match goal with H : ro_cells _ _ A _ |- _ => exact H end
          | |- bytes_at _ _ ?A _ => match goal with H : bytes_at _ _ A _ |- _ => exact H end
          | |- u8arr _ _ ?A _ => match goal with H : u8arr _ _ A _ |- _ => exact H end
          end
        | eassumption ].
Local Ltac fast_assumption :=
  lazymatch goal with
  | |- ?G => tryif has_evar G then assumption else
             first [ lazymatch G with
                     | rw_cells _ _ ?A _ => match goal with H : rw_cells _ _ A _ |- _ => exact H end
                     | ro_cells _ _ ?A _ => match goal with H : ro_cells _ _ A _ |- _ => exact H end
                     | bytes_at _ _ ?A _ => match goal with H : bytes_at _ _ A _ |- _ => exact H end
                     | u8arr _ _ ?A _ => match goal with H : u8arr _ _ A _ |- _ => exact H end
                     end
                   | assumption ]
  end.
(* [comment removed for export] *)
Local Ltac notrap ::=
  let K := fresh "KT" in
  step; if_cases K; zify_cond K;
  [ exfalso;
    first [ rewrite land7_mod8 in K; first [ match goal with H : _ |- _ => exact (K H) end | lia ]
          | lia
          | rewrite land3_mod4 in K; first [ match goal with H : _ |- _ => exact (K H) end | lia ]
          | rewrite lxor_m1_64 in K by lia; lia
          | rewrite land6_of_mod8 in K by lia; lia
          | rewrite land4_of_mod8 in K by lia; lia
          | let t := type of K in fail 100 "notrap: cannot refute the trap condition" t ]
  | clear K ].

(* [comment removed for export] *)
Ltac post_call_keep segs m :=
  let ms' := fresh "ms'" in let PO := fresh "POST" in
  intros ms' PO;
  destruct_exs PO;
  let E := fresh "E" in let MUc := fresh "MUc" in let WMc := fresh "WMc" in let MIc := fresh "MI" in
  destruct PO as [E [MUc [WMc PO]]];
  first [ destruct PO as [MIc PO] | rename PO into MIc ];
  subst ms';
  lazymatch type of MUc with
  | munch _ m ?m' =>
      transport_after_call segs m m' MUc WMc;
      try match goal with H : mem_inv segs m |- _ => clear H end
  end;
  try destruct_ands PO;
  try (lazymatch goal with
  | |- evt _ _ (MS _ _ (ret_pc (Z_to_bv 64 ?n)) _ _ _ _) =>
      replace (ret_pc (Z_to_bv 64 n)) with (Z_to_bv 64 n) by (symmetry; apply ret_pc_even; [ lia | reflexivity ])
  end).
Ltac head_of' t := lazymatch t with ?f _ => head_of' f | _ => t end.
Tactic Notation "callK" uconstr(SPEC) :=
  lazymatch goal with
  | |- evt ?segs _ (MS _ _ _ _ _ ?m _) =>
      eapply evt_cut; [ eapply SPEC | let ms' := fresh "ms'" in let PO := fresh "PO" in
                                      intros ms' PO; (let h := head_of' ltac:(type of PO) in try unfold h in PO);
                                      try unfold SZ_SCH in PO; try unfold SZ_BS in PO;
                                      rewrite ?unsigned_lit in PO by lia; rewrite ?Z.add_0_r in PO; revert ms' PO; post_call_keep segs m ]
  end.

Ltac if_tk := let K := fresh "K" in if_cases K;
  [ clear K | exfalso; zify_cond K; unfold wz in K; rewrite ?unsigned_lit in K by lia; first [lia | congruence] ].
Ltac if_nt := let K := fresh "K" in if_cases K;
  [ exfalso; zify_cond K; unfold wz in K; rewrite ?unsigned_lit in K by lia; first [lia | congruence] | clear K ].

