(* [comment removed for export] *)
Definition FZ_H1_STACK : Z := 48 + SSVC_SHUTDOWN_STACK.

(* [comment removed for export] *)
Definition ExcFrame (c8 : cell) (vs2 vs1 vs0 vra : word) (j0 : list byte) : list cell :=
  [CB 8 j0; c8; C8 vs2; C8 vs1; C8 vs0; C8 vra].

Ltac sched_cells SCH := let X := fresh "SHD" in
  pose proof SCH as (_ & _ & _ & _ & _ & _ & _ & _ & _ & X & _); unfold sched_hdr, sch_shut, SvcHdrCells, wz in X;
  cbn [sch_hdr sv_vptr sv_ti sv_id sv_owner sv_next sv_destroy] in X; unfold VP_SCHED, L_TYPEID_SCHED, P_DESTROY_ALLOC_SCHED in X.
