Ltac clear_vts := repeat match goal with Hv : rw_cells usegs _ 0x7fbc8 _ |- _ => clear Hv | Hv : rw_cells usegs _ 0x7ee50 _ |- _ => clear Hv
                                   | Hv : rw_cells usegs _ 0x7e718 _ |- _ => clear Hv end.

(* [comment removed for export] *)
Definition fzH1a_post (gp tp s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P regb cfgb schedb v q va i lo : Z) (LB : list block) (m : mem) : machine_state -> Prop :=
  fun ms' => exists ra t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' vs1 vs0 j0 j8,
    ms' = MS (mkR ra (Z_to_bv 64 (P + -48)) gp tp t0 t1 t2 (Z_to_bv 64 (P + 392)) (Z_to_bv 64 v)
                  a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_FZ_PASS2) fc None m' (seg_rom usegs)
    /\ munch [(lo, P); (q + 32, q + 72); (schedb, schedb + SZ_SCH)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (P + -48)
    /\ rw_cells usegs m' (P + -48) (ExcFrame (CB 8 j8) s2 vs1 vs0 (Z_to_bv 64 P_FZ_RET_EXC) j0)
    /\ StreamSvc LB m' v (ssvc_hdr (P + 392) schedb) q
    /\ ImplBlock LB m' q (mkIMPL (mkSPC VP_SPCI_IMPL 1 1 i) 0 va [] 1)
    /\ Scheduler LB m' schedb (mkSCH (sched_hdr (P + 392) cfgb) 0 0 1).

Definition fzH1b_post (gp tp s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P regb cfgb schedb v q va i lo : Z) (LB : list block) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR (Z_to_bv 64 P_FZ_RET_DSV) (Z_to_bv 64 (P + -48)) gp tp t0 t1 t2 (Z_to_bv 64 (P + 392)) (Z_to_bv 64 regb)
                  (Z_to_bv 64 v) a1 a2 a3 a4 a5 a6 a7 (Z_to_bv 64 schedb) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_DESTROY_ALLOC_SSVC) fc None m' (seg_rom usegs)
    /\ munch [(lo, P + -48); (q + 32, q + 72); (schedb, schedb + SZ_SCH)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (P + -48)
    /\ StreamSvc LB m' v (ssvc_hdr (P + 392) schedb) q
    /\ ImplBlock LB m' q (mkIMPL (mkSPC VP_SPCI_IMPL 1 1 i) 0 va [] 1)
    /\ Scheduler LB m' schedb (mkSCH (sched_hdr (P + 392) cfgb) 0 0 1).

(* [comment removed for export] *)
Definition fzH1_hyps (m : mem) (P allocb regb cfgb schedb v q va i lo : Z) (LB : list block) (shut : Z) : Prop :=
  rw_cells usegs m (P + 392) (IoCtxCells allocb regb schedb)
  /\ Registry LB m regb (P + 392) v 0 /\ 0 < regb /\ regb mod 8 = 0 /\ regb + NEWSZ_REG <= hceil          (* [comment removed for export] *)
  /\ StreamSvc LB m v (ssvc_hdr (P + 392) schedb) q /\ 0 < v /\ v mod 8 = 0 /\ v + NEWSZ_SSVC <= hceil
  /\ ImplBlock LB m q (mkIMPL (mkSPC VP_SPCI_IMPL 1 1 i) 0 va [] 1)
  /\ Scheduler LB m schedb (mkSCH (sched_hdr (P + 392) cfgb) 0 0 shut) /\ 0 < schedb /\ schedb mod 16 = 0 /\ schedb + NEWSZ_SCH <= hceil
  /\ (schedb + NEWSZ_SCH <= 0x10000 \/ 0xb8000 <= schedb)
  /\ ConfigSvc LB m cfgb (cfg_hdr (P + 392)) /\ 0 < cfgb /\ cfgb mod 8 = 0 /\ cfgb + NEWSZ_CFG <= hceil        (* [comment removed for export] *)
  /\ (v + NEWSZ_SSVC <= q \/ q + SZ_SPCI_IMPL <= v) /\ (va + 8 <= q \/ q + SZ_SPCI_IMPL <= va)
  /\ (regb + NEWSZ_REG <= q \/ q + SZ_SPCI_IMPL <= regb) /\ (regb + NEWSZ_REG <= schedb \/ schedb + NEWSZ_SCH <= regb)
  /\ (v + NEWSZ_SSVC <= schedb \/ schedb + NEWSZ_SCH <= v) /\ (cfgb + NEWSZ_CFG <= q \/ q + SZ_SPCI_IMPL <= cfgb)
  /\ (cfgb + NEWSZ_CFG <= schedb \/ schedb + NEWSZ_SCH <= cfgb) /\ (q + SZ_SPCI_IMPL <= schedb \/ schedb + NEWSZ_SCH <= q)
  /\ (va + 8 <= schedb \/ schedb + NEWSZ_SCH <= va)
  /\ XStatics m
  /\ hceil <= lo /\ P mod 16 = 0 /\ P + 512 < 2^64
  /\ mem_inv usegs m.

Section H1.
  Variables (P allocb regb cfgb schedb v q va i lo : Z) (LB : list block).

(* [comment removed for export] *)
Ltac h1_intro :=
  intros HY ST LO; destruct HY as (IOC & REG & R0 & R8 & RH & SV & V0 & V8 & VH & IB & SCH & S0 & S16 & SH & S5 & CFG & C0 & C8 & CH & DVQ & DAQ & DRQ & DRS & DVS & DCQ
                              & DCS & DQS & DAS & XS & CEIL & AL & PHI & MI);
  pose proof LO as LO'; unfold FZ_H1_STACK, SSVC_SHUTDOWN_STACK, MTX_UNLOCK_STACK in LO;
  (* [comment removed for export] *)
  let LV := fresh "LV" in let LS := fresh "LS" in let LC := fresh "LC" in let LR := fresh "LR" in
  let AL48 := fresh "AL48" in let S8 := fresh "S8" in
  assert (LV : Z.land v 7 = 0) by (rewrite land7_mod8; exact V8);
  assert (S8 : schedb mod 8 = 0) by (apply mod8_of_mod16; exact S16);
  assert (LS : Z.land schedb 7 = 0) by (rewrite land7_mod8; exact S8);
  assert (LC : Z.land cfgb 7 = 0) by (rewrite land7_mod8; exact C8);
  assert (LR : Z.land regb 7 = 0) by (rewrite land7_mod8; exact R8);
  assert (AL48 : (P + -48) mod 16 = 0) by (clear - AL; Z.div_mod_to_equations; lia);
  change (alg 8 v) in V8; change (alg 16 schedb) in S16; change (alg 8 schedb) in S8; change (alg 8 cfgb) in C8; change (alg 8 regb) in R8;
  change (alg 16 P) in AL; change (alg 16 (P + -48)) in AL48;
  unfold NEWSZ_REG, NEWSZ_SSVC, SZ_SPCI_IMPL, NEWSZ_SCH, NEWSZ_CFG in *;
  pose proof IB as (pq & jq7 & INQ & RBQ & _ & _ & _ & _ & _ & _ & VST); pose proof RBQ as (Q1 & _ & _ & Q4 & _); unfold SZ_SPCI_IMPL in Q4;
  cbn [im_vcap im_vb im_states zlength length] in VST;
  destruct VST as [[K _]|(pva & jva & INVA & RBVA & _)]; [lia|]; pose proof RBVA as (VA1 & _ & _ & VA4 & _); clear RBVA;
  hcb;
  (* [comment removed for export] *)
  pose proof REG as (pr & j0 & j7 & INR & _ & _ & ROF & _); unfold O_REG_OWNER, wz in ROF;
  pose proof SV as (pv & vj7 & INV & VCH & _); unfold ssvc_hdr, SvcHdrCells, CookieCells, O_SPC_STORAGE, wz in VCH;
  cbn [sv_vptr sv_ti sv_id sv_owner sv_next sv_destroy app] in VCH;
  pose proof CFG as (pc & jc4 & jc7 & INC & CCH & _); unfold cfg_hdr, SvcHdrCells, CookieCells, wz in CCH;
  cbn [sv_vptr sv_ti sv_id sv_owner sv_next sv_destroy app] in CCH;
  unfold IoCtxCells, wz in IOC;
  unfold VP_SSVC, VP_SCHED, VP_CONFIG_SVC, L_TYPEID_SCHED, L_TYPEID_CONFIG, G_ID_SSVC, P_DESTROY_ALLOC_SSVC, P_DESTROY_ALLOC_SCHED, P_DESTROY_ALLOC_CONFIG in *;
  sched_cells SCH; vts XS.

(* [comment removed for export] *)
Ltac h1_node := step; notrap; step; step; step; step.

Ltac h1_pass shut :=
  (* [comment removed for export] *)
  h1_node;
  clear_vts;
  let SS := fresh "SS" in
  pose proof ssvc_shutdown_spec as SS; unfold ssvc_shutdown_stmt, wz in SS;
  lazymatch goal with SV : StreamSvc _ _ _ _ _, IB : ImplBlock _ _ _ _, ST : stk _ _ _ _ |- _ =>
    callK (SS v q lo LB (ssvc_hdr (P + 392) schedb) (mkIMPL (mkSPC VP_SPCI_IMPL 1 1 i) 0 va [] 1));
    [ exact SV | lia | fast_assumption | unfold NEWSZ_SSVC; lia | exact IB | reflexivity | reflexivity
      | unfold NEWSZ_SSVC, SZ_SPCI_IMPL; lia | cbn [im_vcap im_vb]; unfold SZ_SPCI_IMPL; intros _; lia
      | rewrite unsigned_lit by lia; exact ST | unfold SSVC_SHUTDOWN_STACK, MTX_UNLOCK_STACK; rewrite unsigned_lit by lia; lia | fast_assumption
      | rewrite unsigned_lit by lia; fast_assumption | rewrite unsigned_lit by lia; reflexivity | fast_assumption | ];
    clear SV IB SS
  end;
  lazymatch goal with MUc : munch _ ?m0 ?m1, WMc : wmono _ _ _, SCH : Scheduler _ _ _ _, XS : XStatics _, RBQ : rblock_range _ _ |- _ =>
    eapply (Scheduler_transport _ _ m0 m1) in SCH; [| exact MUc| exact WMc| unfold NEWSZ_SCH; cbn; lia];
    let X := fresh "XS" in
    assert (X : XStatics m1) by (eapply XStatics_keep; [exact XS| exact MUc| exact WMc|];
       pose proof RBQ as (_ & _ & _ & _ & Q5); unfold SZ_SPCI_IMPL in Q5; constructor; [cbn; lia|]; constructor; [cbn; lia| constructor]);
    clear XS MUc WMc; rename X into XS; try clear m0; vts XS
  end;
  (* [comment removed for export] *)
  step; step; if_tk; h1_node;
  clear_vts; try match goal with Hs : rw_cells usegs _ schedb _ |- _ => clear Hs end;
  let SD := fresh "SD" in
  pose proof sched_shutdown_spec as SD; unfold sched_shutdown_stmt, wz in SD;
  lazymatch goal with SCH : Scheduler _ _ _ _, ST : stk _ _ _ _ |- _ =>
    callK (SD schedb lo LB (mkSCH (sched_hdr (P + 392) cfgb) 0 0 shut));
    [ exact SCH | reflexivity | lia | fast_assumption | unfold NEWSZ_SCH; lia
      | rewrite unsigned_lit by lia; exact ST | unfold SCHED_SHUTDOWN_STACK, CEM_UNLOCK_STACK, MUTEX_UNLOCK_STACK; rewrite unsigned_lit by lia; lia | fast_assumption
      | rewrite unsigned_lit by lia; fast_assumption | rewrite unsigned_lit by lia; reflexivity | fast_assumption | ];
    clear SCH SD
  end;
  lazymatch goal with MUc : munch _ ?m0 ?m1, WMc : wmono _ _ _, SV : StreamSvc _ _ _ _ _, IB : ImplBlock _ _ _ _, XS : XStatics _ |- _ =>
    eapply (StreamSvc_transport _ _ m0 m1) in SV; [| exact MUc| exact WMc| unfold NEWSZ_SSVC; cbn; lia];
    eapply (ImplBlock_transport _ _ m0 m1) in IB; [| exact MUc| exact WMc| unfold SZ_SPCI_IMPL; cbn; lia| cbn [im_vcap im_vb]; intros _; cbn; lia];
    let X := fresh "XS" in
    assert (X : XStatics m1) by (eapply XStatics_keep; [exact XS| exact MUc| exact WMc|];
       constructor; [cbn; lia|]; constructor; [cbn; lia| constructor]);
    clear XS MUc WMc; rename X into XS; try clear m0; vts XS
  end;
  lazymatch goal with SCH : Scheduler _ _ _ _ |- _ => cbn [sch_shut sch_hdr sch_stopped] in SCH; sched_cells SCH end;
  (* [comment removed for export] *)
  step; step; if_tk; h1_node;
  let CSD := fresh "CSD" in
  pose proof config_shutdown_spec as CSD; unfold ret_stmt, P_CONFIG_SHUTDOWN in CSD;
  call CSD; [fast_assumption|]; clear CSD;
  (* [comment removed for export] *)
  step; step; if_nt.
