Definition fzH3_post (gp tp s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P regb cfgb : Z) (LB : list block) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR (Z_to_bv 64 P_FZ_RET_DSV) (Z_to_bv 64 (P + -48)) gp tp t0 t1 t2 (Z_to_bv 64 (P + 392)) (Z_to_bv 64 regb)
                  (Z_to_bv 64 cfgb) a1 a2 a3 a4 a5 a6 a7 (Z_to_bv 64 0) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_DESTROY_ALLOC_CONFIG) fc None m' (seg_rom usegs)
    /\ munch [(regb + 56, regb + 64)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ Registry LB m' regb (P + 392) cfgb 0.

Lemma fzH3 : forall gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P regb cfgb fst0 : Z) (LB : list block),
  Registry LB m regb (P + 392) fst0 0 -> regb + NEWSZ_REG <= hceil ->
  ConfigSvc LB m cfgb (cfg_hdr (P + 392)) -> 0 < cfgb -> cfgb + NEWSZ_CFG <= hceil ->
  (regb + NEWSZ_REG <= cfgb \/ cfgb + NEWSZ_CFG <= regb) ->
  cfgb mod 8 = 0 ->                                                                     (* [comment removed for export] *)
  0 <= P + -48 -> P + 512 < 2^64 ->
  mem_inv usegs m ->
  evt usegs (fzH3_post gp tp s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P regb cfgb LB m)
    (MS (mkR (Z_to_bv 64 P_FZ_RET_DSV) (Z_to_bv 64 (P + -48)) gp tp t0 t1 t2 (Z_to_bv 64 (P + 392)) (Z_to_bv 64 regb) a0 a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 cfgb) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_FZ_RET_DSV) fc None m (seg_rom usegs)).
