    (P allocb regb lo : Z) (LB : list block) (vs2 vs1 vs0 vra : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' j0,
    ms' = MS (mkR (Z_to_bv 64 P_FZ_RET_ATD) (Z_to_bv 64 (P + -48)) gp tp t0 t1 t2 (Z_to_bv 64 (P + 392)) (Z_to_bv 64 regb)
                  (Z_to_bv 64 (P + -40)) (Z_to_bv 64 regb) (Z_to_bv 64 1) a3 a4 a5 a6 a7 (Z_to_bv 64 0) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
