    /\ munch [(regb + 56, regb + 64); (lo, P + -32)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (P + -48)
    /\ Registry LB m' regb (P + 392) 0 0
    /\ rw_cells usegs m' (P + -48) (ExcFrame (C8 (wz allocb)) vs2 vs1 vs0 vra j0).

Lemma fzH4 : forall gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
