  Registry LB m regb (P + 392) fst0 0 -> regb + NEWSZ_REG <= hceil ->
  0 < regb -> regb mod 8 = 0 ->                                                         (* [comment removed for export] *)
  rw_cells usegs m (P + 392) (IoCtxCells allocb regb schedb) ->
  rw_cells usegs m (P + -48) (ExcFrame (CB 8 j8) vs2 vs1 vs0 vra j0) ->
  stk usegs m lo (P + -48) -> lo + 16 <= P + -48 -> hceil <= lo -> P + 512 < 2^64 ->
  mem_inv usegs m ->
  evt usegs (fzH4_post gp tp s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P allocb regb lo LB vs2 vs1 vs0 vra m)
    (MS (mkR (Z_to_bv 64 P_FZ_RET_DSV) (Z_to_bv 64 (P + -48)) gp tp t0 t1 t2 (Z_to_bv 64 (P + 392)) (Z_to_bv 64 regb) a0 a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 0) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
