(* [comment removed for export] *)
Definition fz_ret_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (W : list (Z * Z)) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 0) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch W m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp).

Lemma fzI0 : forall gp tp t0 t1 t2 s0x s1x a0 a1 a2 a3 a4 a5 a6 a7 s2x s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P lo : Z) (ra s0 s1 s2 vs1 vs0 c8v : word) (j0 : list byte) (cs : list cell),
  rw_cells usegs m (P + -48) (ExcFrame (C8 c8v) s2 vs1 vs0 (Z_to_bv 64 P_FZ_RET_EXC) j0) ->
  stk usegs m lo (P + -48) -> stk usegs m P (P + 416) ->
  rw_cells usegs m (P + 416) (FlatBufCells FB_empty) ->
  rw_cells usegs m (P + 464) cs -> cells_size cs = 24%nat ->
  rw_cells usegs m (P + 488) [C8 s1; C8 s0; C8 ra] ->
  hceil <= lo -> lo <= P + -48 -> P + 512 < 2^64 -> bv_unsigned ra mod 2 = 0 ->
  mem_inv usegs m ->
