(* [comment removed for export] *)
Lemma fzJ : forall rax gp tp t0 t1 t2 s0x s1x a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P lo : Z) (ra s0 s1 : word) (cF cE : list cell),
  rw_cells usegs m (P + 488) [C8 s1; C8 s0; C8 ra] ->
  rw_cells usegs m (P + 416) cF -> cells_size cF = 48%nat -> rw_cells usegs m (P + 464) cE -> cells_size cE = 24%nat ->
  stk usegs m lo (P + 416) -> hceil <= lo -> lo <= P -> P + 512 < 2^64 -> bv_unsigned ra mod 2 = 0 ->
  mem_inv usegs m ->
  evt usegs (fz_ret_post ra (Z_to_bv 64 (P + 512)) gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc [] lo m)
    (MS (mkR rax (Z_to_bv 64 P) gp tp t0 t1 t2 s0x s1x a0 a1 a2 a3 a4 a5 a6 a7
             s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
